#include <iostream>
using namespace std;

bool isOdd(int n) {
    return (n & 1) == 1;
}

bool isEven(int n) {
    return (n & 1) == 0;
}

int main() {
    int n;
    cin >> n;

    if (isEven(n)) {
        cout << n << " 是偶数" << endl;
    } else {
        cout << n << " 是奇数" << endl;
    }

    cout << "1 到 " << n << " 中的奇数: ";
    for (int i = 1; i <= n; i += 2) {
        cout << i << " ";
    }
    cout << endl;

    int arr[] = {3, 7, 2, 8, 5, 10};
    int oddCount = 0, evenCount = 0;
    for (int i = 0; i < 6; i++) {
        if (isEven(arr[i])) evenCount++;
        else oddCount++;
    }
    cout << "奇数个数: " << oddCount << ", 偶数个数: " << evenCount << endl;

    return 0;
}

#include <iostream>
using namespace std;

bool isDivisible(int a, int b) {
    return b != 0 && a % b == 0;
}

bool isDivBy3(int n) {
    int sum = 0;
    n = abs(n);
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum % 3 == 0;
}

int main() {
    int n;
    cin >> n;

    cout << n << " 能被 2 整除? " << (isDivisible(n, 2) ? "是" : "否") << endl;
    cout << n << " 能被 3 整除? " << (isDivisible(n, 3) ? "是" : "否") << endl;
    cout << n << " 能被 5 整除? " << (isDivisible(n, 5) ? "是" : "否") << endl;

    cout << "用数字和判断 3 的倍数: " << (isDivBy3(n) ? "是" : "否") << endl;

    cout << "1 到 " << n << " 中 3 的倍数: ";
    for (int i = 3; i <= n; i += 3) {
        cout << i << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> getFactors(int n) {
    vector<int> factors;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i != n / i) {
                factors.push_back(n / i);
            }
        }
    }
    sort(factors.begin(), factors.end());
    return factors;
}

int countFactors(int n) {
    int cnt = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            cnt++;
            if (i != n / i) cnt++;
        }
    }
    return cnt;
}

int main() {
    int n;
    cin >> n;

    vector<int> factors = getFactors(n);
    cout << n << " 的所有因数: ";
    for (int f : factors) {
        cout << f << " ";
    }
    cout << endl;

    cout << "因数个数: " << countFactors(n) << endl;
    cout << "因数之和: ";
    int sum = 0;
    for (int f : factors) sum += f;
    cout << sum << endl;

    return 0;
}

#include <iostream>
using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int n;
    cin >> n;

    if (isPrime(n)) {
        cout << n << " 是质数" << endl;
    } else {
        cout << n << " 不是质数" << endl;
    }

    cout << "1 到 100 中的质数: " << endl;
    int cnt = 0;
    for (int i = 2; i <= 100; i++) {
        if (isPrime(i)) {
            cout << i << " ";
            cnt++;
        }
    }
    cout << endl << "共 " << cnt << " 个" << endl;

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

struct Factor {
    int prime;
    int power;
};

vector<Factor> factorize(int n) {
    vector<Factor> result;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            Factor f;
            f.prime = i;
            f.power = 0;
            while (n % i == 0) {
                n /= i;
                f.power++;
            }
            result.push_back(f);
        }
    }
    if (n > 1) {
        result.push_back({n, 1});
    }
    return result;
}

int main() {
    int n;
    cin >> n;

    vector<Factor> factors = factorize(n);

    cout << n << " = ";
    for (int i = 0; i < factors.size(); i++) {
        if (i > 0) cout << " × ";
        cout << factors[i].prime;
        if (factors[i].power > 1) {
            cout << "^" << factors[i].power;
        }
    }
    cout << endl;

    int divisorCount = 1;
    for (auto& f : factors) {
        divisorCount *= (f.power + 1);
    }
    cout << "因数个数: " << divisorCount << endl;

    return 0;
}

#include <iostream>
using namespace std;

int gcd(int a, int b) {
    return b ? gcd(b, a % b) : a;
}

int gcdIterative(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int extGcd(int a, int b, int& x, int& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    int x1, y1;
    int g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    int a = 48, b = 18;
    cout << "gcd(" << a << ", " << b << ") = " << gcd(a, b) << endl;

    cout << "辗转相除过程: " << endl;
    int x = a, y = b;
    while (y) {
        cout << x << " = " << x/y << " × " << y << " + " << x%y << endl;
        int t = x % y;
        x = y;
        y = t;
    }
    cout << "gcd = " << x << endl;

    int ex, ey;
    int g = extGcd(48, 18, ex, ey);
    cout << "48×" << ex << " + 18×" << ey << " = " << g << endl;

    return 0;
}

#include <iostream>
using namespace std;

int gcd(int a, int b) {
    return b ? gcd(b, a % b) : a;
}

long long lcm(int a, int b) {
    return (long long)a / gcd(a, b) * b;
}

long long lcmMulti(int arr[], int n) {
    long long result = arr[0];
    for (int i = 1; i < n; i++) {
        result = lcm(result, arr[i]);
        if (result > 1e18) break;
    }
    return result;
}

int main() {
    int a = 12, b = 18;
    cout << "gcd(" << a << ", " << b << ") = " << gcd(a, b) << endl;
    cout << "lcm(" << a << ", " << b << ") = " << lcm(a, b) << endl;
    cout << "验证: gcd × lcm = " << (long long)gcd(a, b) * lcm(a, b) << endl;
    cout << "验证: a × b = " << (long long)a * b << endl;

    int arr[] = {4, 6, 8, 12};
    cout << "lcm(4, 6, 8, 12) = " << lcmMulti(arr, 4) << endl;

    cout << "\n分数通分示例: 1/6 + 1/8" << endl;
    int d = lcm(6, 8);
    cout << "公分母: " << d << endl;
    cout << d/6 << "/" << d << " + " << d/8 << "/" << d;
    cout << " = " << (d/6 + d/8) << "/" << d << endl;

    return 0;
}

#include <iostream>
using namespace std;
typedef long long ll;

ll power(ll a, ll b, ll mod) {
    ll res = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

ll inv(ll a, ll mod) {
    return power(a, mod - 2, mod);
}

int main() {
    ll a, mod;
    cin >> a >> mod;
    cout << inv(a, mod) << endl;
    cout << a * inv(a, mod) % mod << endl;
    return 0;
}
